select CONCAT(IFNULL(LEFT(grade, 1), ''), class_name, '班') as className,
count(class_name) * #{score} as classCount
from miniprograme.singleMoralRecord
where school = #{school}

    and label = #{label}


    and grade = #{grade}

and check_date between #{startDate} and #{endDate}
group by grade, class_name  
order by classCount desc

select * from miniprograme.singleMoralRecord where school = #{school} and check_date between #{startDate} and
#{endDate}

    and grade = #{grade}
